    path = join(
      fixture.home,
      '.codex',
      'sessions',
      '2026',
      '09',
      '30',
      `rollout-2026-09-30T12-00-00-${sourceId}.jsonl`,
    );
    rows = [
      {
        type: 'session_meta',
        timestamp,
        payload: {
          id: sourceId,
          timestamp,
          cwd: fixture.source,
          originator: 'codex_cli_rs',
          cli_version: '0.157.1',
          source: 'cli',
          model_provider: 'openai',
        },
      },
      ...[
        {
          type: 'message',
