import { fileURLToPath, pathToFileURL } from 'node:url';
// Protects against native terminal loaders losing imported tools or persisted replies; noninteractive lifecycle tests do not exercise the exact printed terminal command.
const repositoryRoot = fileURLToPath(
  new URL('../../../../../../', import.meta.url),
);
const helper = join(
  repositoryRoot,
  'src/skills/session-fork-to-destination/src/helpers/import-native-clients-support.ts',
);
