  createFixture,
  app,
  codexConfig,
  hash,
  history,
  run,
  sourceTranscript,
  sourceId,
} = await import(pathToFileURL(helper).href);
const provider = process.argv[2] as 'codex' | 'claude';
assert(['codex', 'claude'].includes(provider));
const evidenceDir = await mkdtemp(
  join(tmpdir(), 'session-import-terminal-evidence-'),
);
console.log(`TERMINAL_EVIDENCE_DIR ${evidenceDir}`);
const generatedSkill = await readFile(
  join(repositoryRoot, 'skills/session-fork-to-destination/SKILL.md'),
  'utf8',
);
const generatedVersion =
  generatedSkill.match(/^  version: ['"]([^'"]+)['"]/m)?.[1] ?? 'unknown';
const f = await createFixture(provider);
const firstReply = `${provider.toUpperCase()}_EXACT_TERMINAL_REPLY_101`;
const secondReply = `${provider.toUpperCase()}_EXACT_TERMINAL_REPLY_102`;
const requests: any[] = [];
const http = createServer(async (req, res) => {
  try {
    let raw = '';
    for await (const chunk of req) {
      raw += String(chunk);
      assert(raw.length < 4 * 1024 * 1024);
    }
    const body = JSON.parse(raw);
    if (req.url?.includes('count_tokens')) {
      res.setHeader('content-type', 'application/json');
      res.end('{"input_tokens":10}');
      return;
    }
    requests.push(body);
    const seq = requests.length;
    await writeFile(
      join(evidenceDir, `${provider}-exact-terminal-all-requests.json`),
      JSON.stringify(requests, null, 2) + '\n',
    );
    const input = JSON.stringify(
      provider === 'codex' ? body.input : body.messages,
    );
    const reply = input.includes('Check previous synthetic reply.')
      ? secondReply
