let live: any;
async function terminal(command: string, label: string) {
  console.log(`EXACT_TERMINAL_START ${label}\n${command}`);
  live = spawn(
    '/usr/bin/sandbox-exec',
    ['-f', f.profile, '/bin/sh', '-c', command],
    { cwd: f.destination, env: f.env, stdio: 'inherit' },
  );
  const timer = setTimeout(() => live.kill('SIGKILL'), 90000);
  const status = await new Promise<number | null>((resolve) =>
    live.once('exit', resolve),
  );
  clearTimeout(timer);
  live = undefined;
  assert.equal(status, 0, `${label} exit status`);
}
function checkRequest(request: any, previous?: string) {
  const content = JSON.stringify(
    provider === 'codex' ? request.input : request.messages,
  );
  for (const text of [
    history.prompt,
    history.answer,
    history.output,
    ...(previous ? [previous] : []),
  ])
    assert(content.includes(text), text);
  if (provider === 'codex') {
    const call = request.input.find(
      (i: any) => i.type === 'function_call' && i.call_id === history.callId,
    );
    assert.equal(call.name, history.tool);
    assert.deepEqual(JSON.parse(call.arguments), history.arguments);
    const output = request.input.find(
      (i: any) =>
        i.type === 'function_call_output' && i.call_id === history.callId,
    );
    assert.equal(output.output, history.output);
  } else {
    const blocks = request.messages.flatMap((m: any) =>
      Array.isArray(m.content) ? m.content : [],
    );
    const call = blocks.find(
      (i: any) => i.type === 'tool_use' && i.id === history.callId,
    );
    assert.equal(call.name, history.tool);
    assert.deepEqual(call.input, history.arguments);
    const output = blocks.find(
      (i: any) => i.type === 'tool_result' && i.tool_use_id === history.callId,
    );
    assert(
      [
        history.output,
        JSON.stringify([{ type: 'text', text: history.output }]),
      ].includes(
        typeof output.content === 'string'
          ? output.content
          : JSON.stringify(output.content),
      ),
    );
  }
}
